/**
 * Engine marks and shared UI icons, free of any `vscode` import so the module
 * stays unit-testable with `node --test`.
 *
 * Engine marks ship inside DataDock under `resources/icon/`:
 *  - `mysql.svg`, `pg_server.svg`, `sqlite-icon.svg` and
 *    `database-container.svg` are the MIT-licensed marks from the reference
 *    Database Client repo (cweijan/vscode-database-client);
 *  - `mariadb.svg` (teal seahorse) and `mssql.svg` (server-stack mark) are
 *    authored inside DataDock.
 *
 * Webviews inline the `svg` strings directly: inline SVG is exempt from the
 * strict CSP (`default-src 'none'` blocks `<img>`) and needs no
 * `asWebviewUri` plumbing. The explorer tree resolves `file` names against
 * `resources/icon/` with `vscode.Uri.file`; Microsoft SQL Server keeps its
 * reference PNG (`mssql_server.png`) for the tree while webviews use the
 * authored `mssql.svg` mark.
 *
 * `ENGINE_SVGS` is byte-exact content from the files above (XML declarations,
 * DOCTYPEs and comments stripped, and `style` declarations rewritten as SVG
 * presentation attributes because the webview CSP has no 'unsafe-inline' for
 * style attributes - see `scripts/gen-engine-svgs.cjs`). Regenerate it after
 * touching the assets by running `node scripts/gen-engine-svgs.cjs`.
 */

import type { EngineId } from '../db/types';

