// __ENGINE_SVGS_END__

export interface EngineIcon {
  /** File name inside `resources/icon/` used by the explorer tree. */
  readonly file: string;
  /** Inline SVG for webviews (never `<img>`). */
  readonly svg: string;
}

/** File the explorer tree should use per engine. */
const ENGINE_FILES: Readonly<Record<string, string>> = {
  mysql: 'mysql.svg',
  mariadb: 'mariadb.svg',
  postgresql: 'pg_server.svg',
  sqlite: 'sqlite-icon.svg',
  mssql: 'mssql_server.png',
};

/** Resolves the mark for any engine; unknown or planned engines get the generic container mark. */
export function getEngineIcon(engine: EngineId): EngineIcon {
  const svg = ENGINE_SVGS[engine] ?? ENGINE_SVGS.fallback;
  const file = ENGINE_FILES[engine] ?? 'database-container.svg';
  return { file, svg };
}

// -- generic UI icons (theme-coloured) --------------------------------------

const VIEWBOX = '0 0 16 16';

/** Base 16x16 icon frame; stroke icons override fill inside their body. */
function ui(body: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${VIEWBOX}" width="14" height="14" fill="currentColor" aria-hidden="true">${body}</svg>`;
}

/** Chevron pointing the given direction (sort marks, pager, expanders). */
export function iconChevron(direction: 'up' | 'down' | 'left' | 'right'): string {
  switch (direction) {
    case 'up':
      return ui('<polygon points="3,10.5 8,5.5 13,10.5"/>');
    case 'down':
      return ui('<polygon points="3,5.5 8,10.5 13,5.5"/>');
    case 'left':
      return ui('<polygon points="10.5,3 5.5,8 10.5,13"/>');
    case 'right':
      return ui('<polygon points="5.5,3 10.5,8 5.5,13"/>');
  }
}

/** Funnel mark for the per-column filter buttons. */
export function iconFunnel(): string {
  return ui('<path d="M3 2h10l-4 5.2v3.9l-2 1.2V7.2L3 2z"/>');
}

/**
 * Key mark for a column declared PRIMARY KEY.
 *
 * Drawn here rather than imported: no reference asset is shipped under a
 * licence that permits reuse, and a font glyph or emoji would break the
 * no-icon-font rule. `stroke="currentColor"` keeps the hue out of the markup -
 * the stylesheet paints it from the `--dd-key` token, so the mark follows the
 * theme instead of hard-coding a yellow.
 */
export function iconKeyMark(): string {
  return ui(
    '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">' +
      '<circle cx="5.2" cy="8" r="3.1"/>' +
      '<path d="M8.3 8h5.5"/>' +
      '<path d="M11.3 8v2.3"/>' +
      '<path d="M13.5 8v1.7"/>' +
      '</g>',
  );
}

/**
 * Hashtag mark for a column declared FOREIGN KEY.
 *
 * The two verticals lean the way a typographic `#` does, but this is a drawn
 * icon, never the `#` character: the grid must not confuse a schema mark with
 * a column that is literally named `#`.
 */
export function iconHashtagMark(): string {
  return ui(
    '<g fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round">' +
      '<path d="M6.9 2.4 5.1 13.6"/>' +
      '<path d="M11.5 2.4 9.7 13.6"/>' +
      '<path d="M2.6 6.1h11"/>' +
      '<path d="M2.3 9.9h11"/>' +
      '</g>',
  );
}

